local ip_base = "72.24."

-- SA UEs
for i = 1, 1200 do
    local third_octet = math.floor((i - 1) / 255) + 1
    local fourth_octet = (i - 1) % 255 + 1

    local ip_address = ip_base
        .. third_octet
        .. "."
        .. fourth_octet

    exec(
        'set_pdu_gateway id=' ..i%255+1 ..
        ' ue_nat_ip=' .. ip_address ..
        ' dl_nat_gw=' .. SERVER_IP_LIST[i % 5 + 1] ..
        ' ul_nat_gw=' .. SERVER_IP_LIST[i % 5 + 1]
    )
end
